// Formata telefone para E.164 (+55DDNÚMERO)
function formatarTelefone(tel) {
  const digitos = tel.replace(/\D/g, '');
  if (digitos.length === 13 && digitos.startsWith('55')) return '+' + digitos;
  if (digitos.length === 11) return '+55' + digitos;
  if (digitos.length === 10) return '+55' + digitos;
  return null;
}

// Formata data BR
function formatarData(dataStr) {
  const d = new Date(dataStr + 'T00:00:00');
  return d.toLocaleDateString('pt-BR');
}

const item = $input.first().json;
const telefoneFormatado = formatarTelefone(item.telefone || '');

if (!telefoneFormatado) {
  throw new Error('Telefone inválido: ' + item.telefone);
}

// Token único para rastreamento
const token = require('crypto').randomBytes(32).toString('hex');

return [{
  json: {
    escala_id:       item.escala_id,
    membro_id:       item.membro_id,
    membro_nome:     item.membro_nome,
    ministerio:      item.ministerio || 'ministério',
    data_formatada:  formatarData(item.data_escala),
    horario:         (item.horario || '').substring(0, 5),
    funcao:          item.funcao || 'voluntário(a)',
    telefone:        telefoneFormatado,
    token:           token,
    // Parâmetros do template na ordem correta
    param1:          item.membro_nome,
    param2:          item.ministerio || 'ministério',
    param3:          formatarData(item.data_escala),
    param4:          (item.horario || '').substring(0, 5),
    param5:          item.funcao || 'voluntário(a)'
  }
}];

