INSERT INTO whatsapp_envios
  (confirmacao_id, message_id, status_api, resposta_api)
SELECT ec.id, '{{ $('HTTP — Enviar template Meta').item.json.messages[0].id }}', 'sent', '{{ JSON.stringify($('HTTP — Enviar template Meta').item.json) }}'
FROM escala_confirmacoes ec
WHERE ec.escala_id = {{ $('Code — Formatar dados e gerar token').item.json.escala_id }}
ORDER BY ec.criado_em DESC LIMIT 1;

UPDATE escala_confirmacoes SET status = 'enviado'
WHERE escala_id = {{ $('Code — Formatar dados e gerar token').item.json.escala_id }}
  AND status = 'pendente';

